import { createInertiaApp } from '@inertiajs/vue3'
import { addCollection } from '@iconify/vue/offline'
import { createApp, h } from 'vue'
import type { DefineComponent } from 'vue'
// Pruned tabler collection (generated by scripts/generate-icons.ts) so <Icon>
// resolves offline instead of fetching from the Iconify API (blocked by CSP).
import tabler from '../generated/tabler-icons.json'
import VueCrud from './layouts/VueCrud.vue'

addCollection(tabler)

const pages = import.meta.glob<{ default: DefineComponent }>('./pages/**/*.vue')

createInertiaApp({
  layout: () => VueCrud,
  resolve: async (name) => {
    const path = `./pages/${name}.vue`
    const load = pages[path]
    if (!load) {
      throw new Error(`Unknown Inertia page "${name}". Expected module at ${path}`)
    }
    return (await load()).default
  },
  setup({ el, App, props, plugin }) {
    createApp({ render: () => h(App, props) })
      .use(plugin)
      .mount(el)
  },
  progress: {
    color: '#4f46e5',
  },
})
